export function utf16ToCodePoint(text: string, utf16Offset: number): number {
  let codePoints = 0;
  for (let i = 0; i < utf16Offset; i++) {
    const unit = text.charCodeAt(i);
    if (unit >= 0xd800 && unit <= 0xdbff) {
      i++;
    }
    codePoints++;
  }
  return codePoints;
}

